class Auto(object):
    """Evaluate a spec with glom's normal (automatic) container semantics.

    Useful inside :class:`Fill`, where strings would otherwise be literals.
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope.new_child({_MODE: False}))

    def __repr__(self):
        return 'Auto(%r)' % (self.spec,)


class Fill(Auto):
    """Build a literal template, evaluating embedded specs and callables.

    Unlike normal glom mode, strings and other scalar values are literals,
    and tuples, lists, sets, and dictionaries are recursively filled.
    """
    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope.new_child({_MODE: True}))

    def __repr__(self):
        return 'Fill(%r)' % (self.spec,)


class Let(object):
    """Bind named subspec results in the scope for subsequent specs.

    For example, ``(Let(value='a'), S.value)`` extracts and saves ``a``.
    The target itself is passed through unchanged.
    """
    def __init__(self, **bindings):
        self.bindings = bindings

    def glomit(self, target, scope):
        values = {name: scope[glom](target, spec, scope)
                  for name, spec in self.bindings.items()}
        scope.maps[1].update(values)
        return target

    def __repr__(self):
        return 'Let(%s)' % ', '.join('%s=%r' % item
                                    for item in self.bindings.items())


def _fill(target, spec, scope):
    recurse = lambda val: scope[glom](target, val, scope)
    if isinstance(spec, dict):
        return type(spec)((recurse(k), recurse(v)) for k, v in spec.items())
    if isinstance(spec, (list, tuple, set, frozenset)):
        return type(spec)(recurse(val) for val in spec)
    if callable(spec):
        return spec(target)
    return spec

